#!/usr/bin/env bash
# Create .env from .env.example with fresh secrets.
#   scripts/init-env.sh example.org         (or: make init DOMAIN=example.org)
# Refuses to overwrite an existing .env: secrets are not re-generated by accident.
# shellcheck source=lib/common.sh
. "$(dirname "$0")/lib/common.sh"

domain="${1:-${DOMAIN:-}}"
[[ -n "$domain" ]] || die "usage: $0 <domain>   e.g. $0 farmanalyser.com.au"
[[ "$domain" =~ ^[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]] || die "not a domain: $domain"
[[ -e "$ENV_FILE" ]] && die "$ENV_FILE already exists — edit it, or move it away first"
require_cmd openssl

tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT

while IFS= read -r line || [[ -n "$line" ]]; do
  line="${line//example.com/$domain}"
  if [[ "$line" == *"__GENERATE__"* ]]; then
    key="${line%%=*}"
    case "$key" in
      CHATWOOT_SECRET_KEY_BASE) line="$key=$(gen_secret 64)" ;;
      *)                        line="$key=$(gen_secret 24)" ;;
    esac
  fi
  printf '%s\n' "$line"
done < "$ROOT_DIR/.env.example" > "$tmp"

install -m 600 "$tmp" "$ENV_FILE"
ok "wrote $ENV_FILE (mode 600) for $domain"
log "next: set CHATWOOT_SMTP_USER / CHATWOOT_SMTP_KEY (Brevo), then: make preflight"
